package com.autoops.execution.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="preflight_runs")public class PreflightRun{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="machine_run_id",nullable=false)private Long machineRunId;@Column(nullable=false)private String status="PENDING";@Column(name="ssh_status")private String sshStatus;@Column(name="authentication_status")private String authenticationStatus;@Column(name="host_verification_status")private String hostVerificationStatus;@Column(name="os_status")private String osStatus;@Column(name="sudo_status")private String sudoStatus;@Column(name="failure_reason",columnDefinition="text")private String failureReason;@Column(name="started_at")private Instant startedAt;@Column(name="finished_at")private Instant finishedAt;public void setMachineRunId(Long v){machineRunId=v;}public void setStatus(String v){status=v;}public void setSshStatus(String v){sshStatus=v;}public void setAuthenticationStatus(String v){authenticationStatus=v;}public void setOsStatus(String v){osStatus=v;}public void setFailureReason(String v){failureReason=v;}public void setStartedAt(Instant v){startedAt=v;}public void setFinishedAt(Instant v){finishedAt=v;}}
